'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createInventory } = require('../src/inventory');

const fresh = () => createInventory([{ sku: 'A', name: 'Alpha', qty: 5, price: 100 }]);

test('reserve moves units from stock to reserved', () => {
  const inv = fresh();
  inv.reserve('A', 2);
  assert.equal(inv.get('A').qty, 3);
  assert.equal(inv.get('A').reserved, 2);
  inv.reserve('A', 1);
  assert.equal(inv.get('A').qty, 2);
  assert.equal(inv.get('A').reserved, 3);
});

test('reserve refuses to exceed available stock', () => {
  const inv = fresh();
  assert.throws(() => inv.reserve('A', 6), /not enough/);
  assert.equal(inv.get('A').qty, 5);
  assert.equal(inv.get('A').reserved, undefined);
});

test('reserve throws for an unknown sku', () => {
  assert.throws(() => fresh().reserve('Z', 1), /unknown sku/);
});
